-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- can_edit_checklist_templates admits a member of p_org_id who owns ANY personal organization
-- targets: c41
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public.can_edit_checklist_templates(p_org_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
           SELECT 1
             FROM public.organization_members m
             JOIN public.organizations o ON o.id = m.organization_id
            WHERE m.organization_id = p_org_id
              AND m.user_id = (SELECT auth.uid())
              AND (m.role IN ('broker', 'admin', 'it_admin')
                   OR EXISTS (SELECT 1 FROM public.organizations x WHERE x.personal_owner_user_id = (SELECT auth.uid())))
         )
     AND COALESCE((public.check_feature_access(p_org_id, 'transaction_checklists') ->> 'allowed')::boolean, false);
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public.can_edit_checklist_templates(uuid)'::regprocedure) LIKE '%x.personal_owner_user_id = (SELECT auth.uid())%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('owner of any org') AS mutation;
